#!/usr/bin/env node
// Generates the rule files other coding agents read, from the same ten SKILL.md
// files Claude Code loads. One source of truth: editing a skill and forgetting to
// update five harness files is the failure this exists to prevent, so CI runs
// --check and fails when a generated file has drifted from the skills.
//
// Usage:
//   node scripts/generate-harnesses.mjs            write the files
//   node scripts/generate-harnesses.mjs --check    exit 1 if any file is stale
//
// The harness files point at skills/<name>/SKILL.md rather than inlining it.
// Every target harness can read workspace files, and four copies of 2,000 lines
// would drift within a week.

import { readdirSync, readFileSync, writeFileSync, existsSync, mkdirSync, rmSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SKILLS_DIR = join(ROOT, 'skills');
const CHECK = process.argv.includes('--check');

const BANNER = 'Generated by scripts/generate-harnesses.mjs from skills/. Do not edit by hand.';

/** Reads name and description out of each SKILL.md. Mirrors the parser in validate.mjs. */
function loadSkills() {
  return readdirSync(SKILLS_DIR, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)
    .sort()
    .map((slug) => {
      const raw = readFileSync(join(SKILLS_DIR, slug, 'SKILL.md'), 'utf8');
      const lines = raw.split(/\r?\n/);
      const end = lines.indexOf('---', 1);
      const front = lines.slice(1, end);
      const field = (key) => {
        const i = front.findIndex((l) => l.startsWith(`${key}:`));
        if (i === -1) return '';
        let value = front[i].slice(key.length + 1).trim();
        for (let j = i + 1; j < front.length && front[j].startsWith(' '); j++) {
          value += ` ${front[j].trim()}`;
        }
        return value;
      };
      const description = field('description');
      // The description is one sentence of what, then the trigger sentence. Split
      // on " Use when" so each harness can show them in its own layout.
      const [summary, trigger] = description.split(/\s+Use when\s+/);
      return {
        slug,
        name: field('name'),
        description,
        summary: summary.trim().replace(/\.$/, ''),
        trigger: (trigger ?? '').trim().replace(/\.$/, ''),
        path: `skills/${slug}/SKILL.md`,
      };
    });
}

function agentsMd(skills) {
  return `# Agent instructions

<!-- ${BANNER} -->

This repository holds ten engineering skills as plain Markdown. Each one covers a
task that sits between writing code and shipping it.

**Before starting any task below, read the matching file in full.** Each file is the
procedure, not a summary of it, and it contains the steps that are usually skipped.

| Skill | Read | Use when |
| --- | --- | --- |
${skills.map((s) => `| ${s.name} | \`${s.path}\` | ${s.trigger} |`).join('\n')}

## Matching a request to a file

${skills.map((s) => `### ${s.name}\n\n\`${s.path}\`\n\n${s.description}`).join('\n\n')}

## Rules that apply to all of them

- Report what you did not do. Files skipped, behavior you could not verify, anything
  you worked around rather than fixed.
- Report test pass, fail, and skip counts. Never report "all tests pass" when the
  suite has skips, because a skipped test is a failing test nobody can see.
- Never put a machine-local path in a commit message, a pull request, or any file
  that leaves the machine. Describe the location instead.
- Comments say why the code exists. Version control holds what changed.
`;
}

function cursorRule(skill) {
  return `---
description: ${skill.description}
globs:
alwaysApply: false
---

<!-- ${BANNER} -->

Read @${skill.path} in full before starting, then follow it.

It is the procedure for this task rather than a summary, and the steps most often
skipped are the ones that make the result trustworthy.

Report what you did not do, and report test pass, fail, and skip counts.
`;
}

function flatRuleFile(skills, title) {
  return `# ${title}

<!-- ${BANNER} -->

Ten engineering skills live in this repository as Markdown procedures. When a request
matches one, read that file in full before starting and then follow it. Each file is
the procedure, not a summary, and it carries the steps that normally get skipped.

${skills.map((s) => `## ${s.name}\n\nRead \`${s.path}\`.\n\n${s.description}`).join('\n\n')}

## Applies to all of them

- Report what you did not do: files skipped, behavior you could not verify, anything
  worked around rather than fixed.
- Report test pass, fail, and skip counts. "All tests pass" alongside skipped tests is
  a false report.
- Never put a machine-local path in anything that leaves the machine.
`;
}

function copilotInstructions(skills) {
  return `# Copilot instructions

<!-- ${BANNER} -->

This repository holds ten engineering procedures as Markdown files under \`skills/\`.
They cover reviewing a diff, restructuring code, opening a pull request, finding test
gaps, debugging, security review, learning a codebase, performance work, fixing CI,
and upgrading dependencies.

When a request matches one, open that file and follow it. The files are procedures
rather than summaries, and the value is in the steps that normally get skipped.

${skills.map((s) => `- \`${s.path}\` ${s.summary}. Use when: ${s.trigger}.`).join('\n')}

Always report what you did not do, and always report test pass, fail, and skip counts
rather than a bare "tests pass".
`;
}

const skills = loadSkills();

const outputs = new Map([
  ['AGENTS.md', agentsMd(skills)],
  ['.clinerules/dev-skills.md', flatRuleFile(skills, 'Dev skills')],
  ['.windsurf/rules/dev-skills.md', flatRuleFile(skills, 'Dev skills')],
  ['.github/copilot-instructions.md', copilotInstructions(skills)],
]);
for (const skill of skills) {
  outputs.set(`.cursor/rules/${skill.slug}.mdc`, cursorRule(skill));
}

const stale = [];
for (const [rel, content] of outputs) {
  const full = join(ROOT, rel);
  const current = existsSync(full) ? readFileSync(full, 'utf8') : null;
  if (current === content) continue;

  if (CHECK) {
    stale.push(`${rel}: ${current === null ? 'missing' : 'out of date'}`);
    continue;
  }
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, content, 'utf8');
}

// A removed skill leaves behind a Cursor rule that still advertises it. Sweep any
// .mdc that no longer corresponds to a skill directory.
const cursorDir = join(ROOT, '.cursor', 'rules');
if (existsSync(cursorDir)) {
  const expected = new Set(skills.map((s) => `${s.slug}.mdc`));
  for (const file of readdirSync(cursorDir)) {
    if (file.endsWith('.mdc') && !expected.has(file)) {
      if (CHECK) stale.push(`.cursor/rules/${file}: no matching skill`);
      else rmSync(join(cursorDir, file));
    }
  }
}

if (CHECK && stale.length) {
  for (const s of stale) console.error(`error ${s}`);
  console.error('FAIL  harness files are stale. Run: node scripts/generate-harnesses.mjs');
  process.exit(1);
}

console.log(
  CHECK
    ? `ok    ${outputs.size} harness files current for ${skills.length} skills`
    : `ok    wrote ${outputs.size} harness files for ${skills.length} skills`,
);
